pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address admin, bool access) public {
        vm.assume(admin != address(0));
        c.adjustAdminAccess(admin, access);
        bytes4 iface = 0xd9b67a26; // type(IERC1155).interfaceId
        assertTrue(c.supportsInterface(iface));
    }
}

